// 1. Input Validation
if (qs_input.current_q_bi == NULL || qs_input.target_q_bi == NULL) {
    qs_state.mode = QS_FAULT;
    qs_output.mode = QS_FAULT;
    qs_output.command_q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    qs_output.error_angle_rad = 0.0;
    qs_output.applied_step_rad = 0.0;
    qs_output.commanded_rate_rad_cycle = 0.0;
    qs_output.braking_rate_rad_cycle = 0.0;
    qs_output.reversal_reset = 0;
    qs_output.slew_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
    qs_output.settled = 0;
    return;
}

if (!isfinite(qs_input.current_q_bi->w) || !isfinite(qs_input.current_q_bi->x) ||
    !isfinite(qs_input.current_q_bi->y) || !isfinite(qs_input.current_q_bi->z) ||
    !isfinite(qs_input.target_q_bi->w) || !isfinite(qs_input.target_q_bi->x) ||
    !isfinite(qs_input.target_q_bi->y) || !isfinite(qs_input.target_q_bi->z)) {
    qs_state.mode = QS_FAULT;
    qs_output.mode = QS_FAULT;
    qs_output.command_q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    qs_output.error_angle_rad = 0.0;
    qs_output.applied_step_rad = 0.0;
    qs_output.commanded_rate_rad_cycle = 0.0;
    qs_output.braking_rate_rad_cycle = 0.0;
    qs_output.reversal_reset = 0;
    qs_output.slew_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
    qs_output.settled = 0;
    return;
}

if (!isfinite(qs_config.max_rate_rad_cycle) || qs_config.max_rate_rad_cycle <= 0.0 ||
    qs_config.max_rate_rad_cycle > PI ||
    !isfinite(qs_config.max_accel_rad_cycle2) || qs_config.max_accel_rad_cycle2 <= 0.0 ||
    !isfinite(qs_config.settle_angle_rad) || qs_config.settle_angle_rad < 0.0 ||
    !isfinite(qs_config.settle_rate_rad_cycle) || qs_config.settle_rate_rad_cycle < 0.0 ||
    qs_config.settle_rate_rad_cycle > qs_config.max_rate_rad_cycle ||
    !isfinite((double)qs_config.settle_cycles) || qs_config.settle_cycles < 1 ||
    qs_config.settle_cycles > 20) {
    qs_state.mode = QS_FAULT;
    qs_output.mode = QS_FAULT;
    qs_output.command_q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    qs_output.error_angle_rad = 0.0;
    qs_output.applied_step_rad = 0.0;
    qs_output.commanded_rate_rad_cycle = 0.0;
    qs_output.braking_rate_rad_cycle = 0.0;
    qs_output.reversal_reset = 0;
    qs_output.slew_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
    qs_output.settled = 0;
    return;
}

// 2. Normalize Quaternions
double norm_curr = sqrt(qs_input.current_q_bi->w*qs_input.current_q_bi->w + 
                        qs_input.current_q_bi->x*qs_input.current_q_bi->x + 
                        qs_input.current_q_bi->y*qs_input.current_q_bi->y + 
                        qs_input.current_q_bi->z*qs_input.current_q_bi->z);
if (norm_curr < ADCS_EPS_QUAT) {
     qs_state.mode = QS_FAULT;
     qs_output.mode = QS_FAULT;
     qs_output.command_q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
     qs_output.error_angle_rad = 0.0;
     qs_output.applied_step_rad = 0.0;
     qs_output.commanded_rate_rad_cycle = 0.0;
     qs_output.braking_rate_rad_cycle = 0.0;
     qs_output.reversal_reset = 0;
     qs_output.slew_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
     qs_output.settled = 0;
     return;
}
adcs_quat_t q_curr_norm;
q_curr_norm.w = qs_input.current_q_bi->w / norm_curr;
q_curr_norm.x = qs_input.current_q_bi->x / norm_curr;
q_curr_norm.y = qs_input.current_q_bi->y / norm_curr;
q_curr_norm.z = qs_input.current_q_bi->z / norm_curr;

double norm_target = sqrt(qs_input.target_q_bi->w*qs_input.target_q_bi->w + 
                          qs_input.target_q_bi->x*qs_input.target_q_bi->x + 
                          qs_input.target_q_bi->y*qs_input.target_q_bi->y + 
                          qs_input.target_q_bi->z*qs_input.target_q_bi->z);
if (norm_target < ADCS_EPS_QUAT) {
     qs_state.mode = QS_FAULT;
     qs_output.mode = QS_FAULT;
     qs_output.command_q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
     qs_output.error_angle_rad = 0.0;
     qs_output.applied_step_rad = 0.0;
     qs_output.commanded_rate_rad_cycle = 0.0;
     qs_output.braking_rate_rad_cycle = 0.0;
     qs_output.reversal_reset = 0;
     qs_output.slew_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
     qs_output.settled = 0;
     return;
}
adcs_quat_t q_target_norm;
q_target_norm.w = qs_input.target_q_bi->w / norm_target;
q_target_norm.x = qs_input.target_q_bi->x / norm_target;
q_target_norm.y = qs_input.target_q_bi->y / norm_target;
q_target_norm.z = qs_input.target_q_bi->z / norm_target;

// 3. Form Relative Quaternion and Extract Angle/Axis
adcs_quat_t q_curr_conj = adcs_quat_conjugate(&q_curr_norm);
adcs_quat_t q_rel = adcs_quat_multiply(&q_target_norm, &q_curr_conj);

// Shortest path
if (q_rel.w < 0.0) {
    q_rel.w = -q_rel.w;
    q_rel.x = -q_rel.x;
    q_rel.y = -q_rel.y;
    q_rel.z = -q_rel.z;
}

double w_clamped = fmin(1.0, fmax(-1.0, q_rel.w));
double half_angle = acos(w_clamped);
double angle_rad = 2.0 * half_angle;

adcs_vec3_t axis_prev = qs_state.previous_axis;
int reversal_reset = 0;

// Check for reversal reset
if (qs_state.axis_valid && angle_rad > ADCS_EPS_NORM) {
    double sin_half = sin(half_angle);
    if (sin_half > ADCS_EPS_NORM) {
        adcs_vec3_t axis_calc = (adcs_vec3_t){q_rel.x / sin_half, q_rel.y / sin_half, q_rel.z / sin_half};
        double dot = adcs_vec3_dot(&axis_calc, &axis_prev);
        if (dot < 0.0) {
            reversal_reset = 1;
            qs_state.commanded_rate_rad_cycle = 0.0;
        }
    }
}

// Calculate slew axis
adcs_vec3_t slew_axis;
if (angle_rad > ADCS_EPS_NORM) {
    double sin_half = sin(half_angle);
    slew_axis.x = q_rel.x / sin_half;
    slew_axis.y = q_rel.y / sin_half;
    slew_axis.z = q_rel.z / sin_half;
    qs_state.axis_valid = 1;
    qs_state.previous_axis = slew_axis;
} else {
    slew_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
    qs_state.axis_valid = 0;
}

// 4. Slew Planning
double commanded_rate = qs_state.commanded_rate_rad_cycle;
double max_rate = qs_config.max_rate_rad_cycle;
double max_accel = qs_config.max_accel_rad_cycle2;
double settle_angle = qs_config.settle_angle_rad;
double settle_rate = qs_config.settle_rate_rad_cycle;
unint32 settle_cycles_req = qs_config.settle_cycles;

// Braking envelope
double braking_rate = sqrt(2.0 * max_accel * angle_rad);

// Target rate
double target_rate = fmin(max_rate, braking_rate);

// Update rate
if (commanded_rate < target_rate) {
    commanded_rate += max_accel;
    if (commanded_rate > target_rate) commanded_rate = target_rate;
} else if (commanded_rate > target_rate) {
    commanded_rate -= max_accel;
    if (commanded_rate < target_rate) commanded_rate = target_rate;
}
if (commanded_rate < 0.0) commanded_rate = 0.0;

// Applied step
double applied_step = fmin(commanded_rate, angle_rad);

// Command Quaternion
double half_step = 0.5 * applied_step;
adcs_quat_t dq;
dq.w = cos(half_step);
double s_step = sin(half_step);
dq.x = slew_axis.x * s_step;
dq.y = slew_axis.y * s_step;
dq.z = slew_axis.z * s_step;

adcs_quat_t q_cmd_norm = adcs_quat_multiply(&dq, &q_curr_norm);

// 5. Settling Logic
if (angle_rad <= settle_angle && commanded_rate <= settle_rate) {
    qs_state.settled++;
} else {
    qs_state.settled = 0;
}

int is_settled = (qs_state.settled >= settle_cycles_req);

// 6. Mode Determination
qs_mode_t current_mode = qs_state.mode;
if (current_mode != QS_HOLD) {
    if (is_settled || angle_rad < ADCS_EPS_NORM) {
        current_mode = QS_HOLD;
        if (angle_rad < ADCS_EPS_NORM) {
            applied_step = 0.0;
            commanded_rate = 0.0;
            q_cmd_norm = q_curr_norm;
        }
    } else {
         if (commanded_rate < max_rate && commanded_rate < braking_rate) {
             current_mode = QS_ACCEL;
         } else if (commanded_rate == max_rate && braking_rate >= max_rate) {
             current_mode = QS_CRUISE;
         } else {
             current_mode = QS_DECEL;
         }
    }
}

qs_state.mode = current_mode;

// 7. Output
qs_output.mode = qs_state.mode;
qs_output.settled = qs_state.settled;
qs_output.error_angle_rad = angle_rad;
qs_output.applied_step_rad = applied_step;
qs_output.commanded_rate_rad_cycle = commanded_rate;
qs_output.braking_rate_rad_cycle = braking_rate;
qs_output.reversal_reset = reversal_reset;
qs_output.slew_axis = slew_axis;
qs_output.command_q_bi = q_cmd_norm;

